#!/usr/bin/env node
/**
 * QA guard for the /ask/ generator's handling of UNTRUSTED question text.
 *
 * Sibling of qa-feedback-render.mjs, which guards how /feedback/ renders the
 * same content client-side. This one guards the other half of the problem:
 * /ask/ pages are generated by scripts/sync-ask.mjs and rendered by Hugo at
 * build time, so they never pass through DOMPurify and are protected by
 * nothing except harden() in the generator.
 *
 * WHY THIS EXISTS
 *   Anyone can type anything into the public form on /feedback/. That text is
 *   posted to GitHub using the site's own PAT, so it arrives owner-authored,
 *   then sync-ask.mjs writes it into Markdown. hugo.toml sets `unsafe = true`
 *   and layouts/ask/single.html emits `.Content`. Without harden(), a stranger
 *   could put live script on an indexed page under Sush's byline. Commit
 *   e04b45aa closed exactly this class of bug on the /feedback/ side.
 *
 * Growing guardrail: every future /ask/ content bug gets a check added here.
 * Never delete checks — they are the memory of customer-facing bugs.
 *
 *   node scripts/qa-ask-render.mjs            # unit + contract checks (~200ms)
 *   node scripts/qa-ask-render.mjs --verbose  # show each hardened result
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = process.env.ASK_QA_ROOT
  ? path.resolve(process.env.ASK_QA_ROOT)
  : path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const VERBOSE = process.argv.includes('--verbose');

let failures = 0, checks = 0;
function check(name, ok, detail) {
  checks++;
  if (ok) console.log(`  \u001b[32mPASS\u001b[0m  ${name}`);
  else { failures++; console.log(`  \u001b[31mFAIL\u001b[0m  ${name}${detail ? '\n        ' + detail : ''}`); }
}

/* sync-ask.mjs runs main() on import, so the helpers are re-created here from
   the real source rather than imported. Reading the source also lets us assert
   the generator still WIRES them up — a perfect harden() that nobody calls is
   the failure mode this pairing is meant to catch. */
const SRC = fs.readFileSync(path.join(ROOT, 'scripts', 'sync-ask.mjs'), 'utf8');

async function loadHarden() {
  /* Extract only the pure hardening functions. They depend on nothing but
     String and RegExp, so lifting them out avoids executing the generator's
     top-level code (which would run main() and hit the network). Each is
     matched as a top-level `function name(...) { … }` closing at column 0. */
  const NAMES = ['redact', 'neutraliseCharRefs', 'neutraliseRawHtml',
    'neutraliseLinkSchemes', 'neutraliseShortcodes', 'harden', 'assertInert'];
  const parts = [];
  for (const n of NAMES) {
    const re = new RegExp(`^function ${n}\\([\\s\\S]*?^\\}`, 'm');
    const m = SRC.match(re);
    if (!m) throw new Error(`sync-ask.mjs no longer defines a top-level ${n}() — the guard cannot verify it`);
    parts.push(m[0]);
  }
  const tmp = path.join(ROOT, 'scripts', `.qa-ask-harden.${process.pid}.mjs`);
  fs.writeFileSync(tmp, parts.join('\n\n') + `\nexport { ${NAMES.join(', ')} };\n`, 'utf8');
  try {
    return await import(pathToFileURL(tmp).href);
  } finally {
    fs.unlinkSync(tmp);
  }
}

/* Payloads a real attacker would try. Each must not survive into markup that a
   browser would execute or that Hugo would expand. */
const PAYLOADS = [
  ['script tag',            '<script>alert(1)</script>'],
  ['img onerror',           '<img src=x onerror=alert(1)>'],
  ['svg onload',            '<svg/onload=alert(1)>'],
  ['iframe',                '<iframe src="https://evil.test"></iframe>'],
  ['body onload',           '<body onload=alert(1)>'],
  ['style tag',             '<style>*{display:none}</style>'],
  ['form hijack',           '<form action="https://evil.test"><input name="p">'],
  ['anchor onmouseover',    '<a href="#" onmouseover="alert(1)">hover</a>'],
  ['js link',               '[click me](javascript:alert(1))'],
  ['js link spaced',        '[click me](  javascript:alert(1))'],
  ['js link upper',         '[click me](JavaScript:alert(1))'],
  ['data uri link',         '[click me](data:text/html;base64,PHNjcmlwdD4=)'],
  ['vbscript link',         '[click me](vbscript:msgbox(1))'],
  ['reference link',        '[ref]: javascript:alert(1)'],
  ['hugo shortcode angle',  '{{< param "secret" >}}'],
  ['hugo shortcode pct',    '{{% include "/etc/passwd" %}}'],
  ['comment breakout',      '<!-- --><script>alert(1)</script>'],
  ['meta refresh',          '<meta http-equiv="refresh" content="0;url=https://evil.test">'],

  /* Parser-disagreement bypasses. Every one of these rendered LIVE markup in
     the first version of harden(), which skipped escaping inside anything that
     merely LOOKED like a code fence or span. Two independent Gate B reviewers
     found them. They are why the guards are now unconditional. Never delete. */
  ['mid-line fence',        'not a fence ```\n<img src=x onerror=alert(1)>'],
  ['mid-line fence crlf',   'not a fence ```\r\n<img src=x onerror=alert(1)>'],
  ['mid-line tilde fence',  'text ~~~\n<img src=x onerror=alert(1)>'],
  ['four-backtick fence',   '````\n<img src=x onerror=alert(1)>'],
  ['escaped fence',         '\\```\n<img src=x onerror=alert(1)>'],
  ['indented fence',        '    ```\n<img src=x onerror=alert(1)>'],
  ['blockquote fence',      '> ```\n<img src=x onerror=alert(1)>'],
  ['list fence',            '- ```\n<img src=x onerror=alert(1)>'],
  ['tilde inside fence',    '```\n~~~\n<img src=x onerror=alert(1)>'],
  ['escaped backtick span', '\\`<img src=x onerror=alert(1)>\\`'],
  ['double-backtick span',  '``code ` here`` <img src=x onerror=alert(1)>'],
  ['comment then svg',      'not a fence ```\n<!--\n-->\n<svg onload=alert(1)>'],

  /* Entity-reconstituted schemes. Goldmark decodes character references inside
     link destinations, and unsafe = true disables its dangerous-URL filter, so
     matching the literal scheme was never enough on its own. */
  ['hex entity colon',      '[e](javascript&#x3a;alert(1))'],
  ['dec entity colon',      '[e](javascript&#58;alert(1))'],
  ['hex entity in scheme',  '[e](jav&#x61;script:alert(1))'],
  ['entity reference link', '[e]: jav&#x61;script:alert(1)'],
];

/* Things a genuine reader writes that must NOT be mangled. A guard that
   destroys legitimate questions gets turned off, so this half matters. */
const LEGITIMATE = [
  ['blockquote',      '> I tried this already'],
  ['bold and italic', 'This is **bold** and _italic_'],
  ['bullet list',     '- one\n- two'],
  ['numbered list',   '1. first\n2. second'],
  ['normal link',     '[the docs](https://learn.microsoft.com/)'],
  ['relative link',   '[my post](/blog/something/)'],
  ['heading',         '## My question'],
  ['inline code',     'run `az login` first'],
  ['less than maths', 'is 3 < 5 always true?'],
  ['table',           '| a | b |\n|---|---|\n| 1 | 2 |'],
  // Named character references Sush writes on purpose. An earlier version
  // escaped every `&` that could begin a reference, so `&lt;N&gt;` reached
  // readers as literal `&lt;N&gt;` on a live page. Never delete these.
  ['entity lt/gt',    'the green "All &lt;N&gt; questions unlocked" row'],
  ['entity typography', 'a &mdash; b &hellip; c &rsquo;d &nbsp; e'],
  ['entity ampersand', 'AT&T and R&D'],
  ['entity escaped amp', 'write &amp;lt; to show a literal entity'],
];

const run = async () => {
  console.log('\n\u001b[1m/ask/ untrusted-content guard\u001b[0m\n');
  const H = await loadHarden();

  console.log('  \u001b[36mHostile payloads are neutralised\u001b[0m');
  /* Decode what Goldmark decodes inside a link destination, so an entity-
     encoded scheme cannot slip past this check by hiding behind `&#x3a;`. */
  const cp = n => (Number.isFinite(n) && n >= 0 && n <= 0x10ffff ? String.fromCodePoint(n) : '');
  const decodeRefs = s => s
    .replace(/&#(\d{1,7});/g, (_, d) => cp(Number(d)))
    .replace(/&#[xX]([0-9a-fA-F]{1,6});/g, (_, h) => cp(parseInt(h, 16)));
  for (const [name, payload] of PAYLOADS) {
    const out = H.harden(payload);
    if (VERBOSE) console.log(`        ${name}: ${JSON.stringify(out)}`);
    // No raw tag opener, no live scheme in link position, no shortcode opener.
    const dec = decodeRefs(out);
    const hasRawTag = /<[a-zA-Z/!?]/.test(out);
    const hasLiveScheme = /\]\(\s*(?:javascript|data|vbscript|file):/i.test(dec)
      || /^\s*\[(?:[^\]\\\n]|\\.)+\]:\s*(?:javascript|data|vbscript|file):/im.test(dec);
    const hasShortcode = /\{\{[<%]/.test(out);
    // Independently, the generator's own fail-closed backstop must refuse it.
    let backstop = null;
    try { H.assertInert(out, 'qa'); } catch (e) { backstop = e.message; }
    check(
      `neutralised: ${name}`,
      !hasRawTag && !hasLiveScheme && !hasShortcode && backstop === null,
      `got: ${JSON.stringify(out)}${backstop ? `\n        backstop: ${backstop}` : ''}`
    );
  }

  console.log('\n  \u001b[36mLegitimate Markdown survives\u001b[0m');
  for (const [name, input] of LEGITIMATE) {
    const out = H.harden(input);
    if (VERBOSE) console.log(`        ${name}: ${JSON.stringify(out)}`);
    // A tag-opening `<` becomes an entity by design; nothing else may change.
    // `3 < 5` is untouched, since `<` before a space cannot open a tag.
    const expected = input.replace(/<(?=[a-zA-Z/!?])/g, '&lt;');
    check(`preserved: ${name}`, out === expected, `in:  ${JSON.stringify(input)}\n        out: ${JSON.stringify(out)}`);
  }

  console.log('\n  \u001b[36mCode content is escaped, deliberately and visibly\u001b[0m');
  /* The first version tried to leave code untouched. Doing that meant guessing
     which regions Goldmark treats as code, and every wrong guess was a bypass.
     Escaping unconditionally is the trade: a tag inside a fence shows as an
     entity. Measured across the live corpus this costs nothing today — no page
     body contains a tag other than the generator's own provenance comment. */
  const fenced = '```html\n<div class="x">hi</div>\n```';
  check(
    'tags inside a fence are escaped rather than left raw',
    H.harden(fenced) === '```html\n&lt;div class="x">hi&lt;/div>\n```',
    JSON.stringify(H.harden(fenced))
  );
  const span = 'use `<br>` for a line break';
  check(
    'tags inside an inline span are escaped',
    H.harden(span) === 'use `&lt;br>` for a line break',
    JSON.stringify(H.harden(span))
  );
  // Hugo expands shortcodes even inside fences, so that one applies everywhere.
  const fencedShortcode = '```\n{{< myshortcode >}}\n```';
  check(
    'shortcode inside a fence is still neutralised',
    !/\{\{[<%]/.test(H.harden(fencedShortcode)),
    JSON.stringify(H.harden(fencedShortcode))
  );
  const unclosed = '```\n<script>alert(1)</script>';
  check(
    'unterminated fence does not become a bypass',
    !/<script/i.test(H.harden(unclosed)),
    JSON.stringify(H.harden(unclosed))
  );
  const maths = 'if (a < b) and 3 <5 and x<3 and 2<=4';
  check(
    'comparisons and maths are left completely alone',
    H.harden(maths) === maths,
    JSON.stringify(H.harden(maths))
  );

  console.log('\n  \u001b[36mGenerator still wires the guard up\u001b[0m');
  check(
    'the question is passed through harden()',
    /const\s+question\s*=\s*harden\(/.test(SRC),
    'harden() exists but the question no longer flows through it'
  );
  check(
    'answers are hardened on the same terms as questions',
    /harden\(redact\(c\.body/.test(SRC),
    'answer bodies no longer flow through harden()'
  );
  check(
    'the code-aware mapper is not reintroduced',
    !/function mapOutsideCode/.test(SRC),
    'mapOutsideCode() is back. Skipping escaping inside guessed code regions is '
      + 'the exact bypass class two Gate B reviewers found; safety must not '
      + 'depend on matching Goldmark\u2019s lexer'
  );
  check(
    'character references are neutralised, and before the rest',
    /function neutraliseCharRefs/.test(SRC)
      && /neutraliseCharRefs\(s\);[\s\S]{0,120}neutraliseRawHtml\(s\);/.test(SRC),
    'entity handling is missing or runs in the wrong order, so an encoded '
      + 'scheme could be reconstituted by Goldmark'
  );
  check(
    'the question is asserted inert before publishing',
    /assertInert\(question,/.test(SRC),
    'the fail-closed backstop no longer covers the question'
  );
  check(
    'answers are asserted inert before publishing',
    /assertInert\(a\.body,/.test(SRC),
    'the fail-closed backstop no longer covers answers'
  );
  check(
    'the email placeholder cannot form a Markdown link label',
    !/'\[email removed\]'/.test(SRC),
    'redact() is inserting `[email removed]` again, which lets a submission '
      + 'manufacture a live link out of text that contained none'
  );
  check(
    'prune is bounded by MAX_PRUNE',
    /stale\.length\s*>\s*MAX_PRUNE/.test(SRC),
    'the unbounded-deletion guard is gone'
  );
  check(
    'fetch floor is enforced',
    /raw\.length\s*<\s*MIN_DISCUSSIONS/.test(SRC),
    'a near-empty fetch would again be treated as mass deletion'
  );
  check(
    'pagination cap fails loudly',
    /Pagination cap hit/.test(SRC),
    'exceeding the page cap would silently return a partial archive'
  );
  /* Gate B round 2 — availability. assertInert is fail-closed and toPage runs
     on every discussion before any filter, so a bare .map() turned one stranger
     submission into a total publishing outage. */
  check(
    'a rejected discussion is quarantined, not fatal',
    /catch\s*\(err\)\s*\{[\s\S]{0,120}quarantined\.push/.test(SRC)
      && !/const all = raw\.map\(d => toPage/.test(SRC),
    'toPage() is being mapped over every discussion without a per-item catch, '
      + 'so a single rejected submission aborts main() and no page is written'
  );
  check(
    'a truncated comment window warns rather than aborting the run',
    /comments\?\.totalCount \|\| 0\) > 20\)[\s\S]{0,200}console\.warn/.test(SRC),
    'the comment-count tripwire throws again. Any account can post 21 comments '
      + 'on a public discussion, which would stop every page from publishing'
  );

  console.log('\n  \u001b[36mThe reason the guard is needed still holds\u001b[0m');
  const hugoCfg = fs.readFileSync(path.join(ROOT, 'hugo.toml'), 'utf8');
  const unsafeOn = /\[markup\.goldmark\.renderer\][\s\S]{0,200}?unsafe\s*=\s*true/.test(hugoCfg);
  /* Deliberately NOT a check(). unsafe=true makes harden() load-bearing, but
     unsafe=false would be an improvement, not a failure — so there is no
     assertion to make here, only a fact to report. An earlier version called
     check(..., true, null), which could never fail and merely inflated the
     count: the same unfalsifiable-assertion defect a reviewer had already
     caught once in this file. */
  console.log(`        note: unsafe = ${unsafeOn ? 'true — harden() is load-bearing' : 'false — harden() is now defence in depth'}`);
  const layout = fs.readFileSync(path.join(ROOT, 'layouts', 'ask', 'single.html'), 'utf8');
  check(
    'ask layout emits .Content (the sink harden() protects)',
    /\{\{\s*\.Content\s*\}\}/.test(layout),
    'layout changed — re-check where untrusted text now lands'
  );

  /* Gate B round 2, second reviewer. Escaping satisfies the HTML parser; it does
     NOT satisfy a second parser that reads textContent (decoded) and reparses it
     through innerHTML. Mermaid does exactly that, so `&lt;img onerror=...>` that
     harden() escaped and assertInert() accepted executed in a real browser. The
     fix is to remove the sink for untrusted sections, not to escape harder. */
  const mermaidHook = fs.readFileSync(
    path.join(ROOT, 'layouts', '_default', '_markup', 'render-codeblock-mermaid.html'), 'utf8');
  check(
    'the mermaid hook excludes untrusted sections',
    /\$untrusted\s*:=\s*slice[^\n]*"ask"/.test(mermaidHook)
      && /in \$untrusted \.Page\.Section/.test(mermaidHook),
    'reader-submitted content can reach Mermaid again. Mermaid decodes this '
      + 'element\u2019s textContent and reparses it as HTML, which revives every '
      + 'tag neutraliseRawHtml() escaped'
  );
  check(
    'the untrusted mermaid path does not re-mark the text as safe HTML',
    /<pre><code class="language-mermaid">\{\{ \.Inner \}\}<\/code><\/pre>/.test(mermaidHook),
    'the ask path is passing .Inner through safeHTML again, which makes this '
      + 'layer depend on harden() having worked — the exact coupling that let '
      + 'the Mermaid bypass through'
  );
  const baseof = fs.readFileSync(path.join(ROOT, 'layouts', '_default', 'baseof.html'), 'utf8');
  check(
    'mermaid.js is not loaded on untrusted sections',
    /not \(in \(slice "ask"\) \.Section\)[\s\S]{0,220}mermaid-11/.test(baseof),
    'ask pages still pull in the Mermaid bundle, which re-arms the sink if the '
      + 'render hook is ever reverted'
  );

  console.log('\n  \u001b[36mThe fail-closed backstop actually fails closed\u001b[0m');
  const rejects = (label, text) => {
    let threw = false;
    try { H.assertInert(text, 'qa'); } catch { threw = true; }
    check(`assertInert rejects ${label}`, threw, `it accepted ${JSON.stringify(text)}`);
  };
  rejects('a raw tag', 'hello <script>alert(1)</script>');
  rejects('a bare shortcode', 'hello {{< param "x" >}}');
  rejects('an entity-encoded scheme', '[e](javascript&#58;alert(1))');
  rejects('a hex entity-encoded scheme', '[e](javascript&#x3a;alert(1))');
  rejects('a literal scheme', '[e](javascript:alert(1))');
  /* Gate B round 2. Browsers strip ASCII whitespace and controls from a URL
     before parsing its scheme, so these two decode to a working `javascript:`.
     A previous version decoded them into the middle of the scheme, which broke
     its own match and waved both through. */
  rejects('a tab entity inside the scheme', '[e](javascript&Tab;:alert(1))');
  rejects('a newline entity splitting the scheme', '[e](java&NewLine;script:alert(1))');
  /* Gate B round 2. The reference-definition form was checked in this harness
     but never in the shipped backstop. */
  rejects('a reference definition scheme', 'see [x][a]\n\n[a]: javascript:alert(1)');
  rejects('a named entity-encoded scheme', '[e](javascript&colon;alert(1))');

  /* Gate B round 2. Being strict here is only safe because a rejection is now
     quarantined per discussion rather than aborting main(). While toPage() was
     mapped over every discussion with no catch, this same strictness meant one
     anonymous form post stopped every page from being written — so the two
     changes are a pair, and the wiring check above is what keeps them together. */
  check(
    'strictness is paired with per-discussion quarantine',
    /quarantined\.push/.test(SRC),
    'assertInert still rejects entity-encoded schemes, but a rejection is fatal '
      + 'again — that combination is a stranger-triggerable publishing outage'
  );
  check(
    'numeric references are still escaped',
    H.harden('x &#58; y &#x3a; z') === 'x &amp;#58; y &amp;#x3a; z',
    `got ${JSON.stringify(H.harden('x &#58; y &#x3a; z'))}`
  );
  /* Gate B round 2. A CommonMark label may contain an escaped `\]`, so the old
     `[^\]]+` stopped one character early and let the scheme through. */
  const escLabel = 'see [click][a\\]b]\n\n[a\\]b]: javascript:alert(1)';
  check(
    'a reference label containing an escaped bracket is still neutralised',
    !/\]:\s*javascript:/i.test(H.harden(escLabel)),
    `got ${JSON.stringify(H.harden(escLabel))}`
  );
  let accepted = true;
  try {
    H.assertInert('A normal question with `code`, [a link](/x/), 3 < 5 and **bold**.', 'qa');
  } catch { accepted = false; }
  check('assertInert accepts ordinary reader text', accepted,
    'the backstop is too strict and would block legitimate questions');

  console.log('\n  \u001b[36mGenerated pages on disk are inert\u001b[0m');
  /* Unit-testing harden() proves the function is sound; this proves the actual
     published bytes are. It is the check that would have caught both bypass
     classes at push time, rather than at Gate B. */
  const askDir = path.join(ROOT, 'content', 'ask');
  const pages = fs.existsSync(askDir)
    ? fs.readdirSync(askDir).filter(f => f.endsWith('.md') && f !== '_index.md')
    : [];
  check('there are generated pages to scan', pages.length > 0, `no .md files under ${askDir}`);
  const offenders = [];
  for (const f of pages) {
    const raw = fs.readFileSync(path.join(askDir, f), 'utf8');
    // Drop the front matter, then the generator's own provenance comment, which
    // is the single tag legitimately present in a generated body.
    const body = raw.split(/^---\s*$/m).slice(2).join('---')
      .replace(/<!--\s*generated by scripts\/sync-ask\.mjs[\s\S]*?-->/g, '');
    try { H.assertInert(body, f); } catch (e) { offenders.push(e.message); }
  }
  check(
    `no generated page carries live markup (${pages.length} scanned)`,
    offenders.length === 0,
    offenders.slice(0, 3).join('\n        ')
  );

  console.log(`\n${failures ? '\u001b[31m' : '\u001b[32m'}${checks - failures}/${checks} checks passed\u001b[0m\n`);
  process.exit(failures ? 1 : 0);
};

run().catch(e => { console.error('✗ qa-ask-render failed:', e); process.exit(1); });
